// Temporary local mock of the Alchemyst v1.context endpoints.
// Used only for local verification of the B2B Newsletter Writer CLI.
// This script is NOT part of the project; it is started separately
// and the CLI is run with ALCHEMYST_AI_BASE_URL pointing at it.

const http = require('http');

const PORT = process.env.MOCK_PORT ? Number(process.env.MOCK_PORT) : 4711;

function readJson(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      if (!raw) return resolve({});
      try {
        resolve(JSON.parse(raw));
      } catch (e) {
        reject(e);
      }
    });
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  // The SDK posts to /api/v1/context/add and /api/v1/context/search.
  // Reply like the real API: JSON body with the documented fields.
  const url = new URL(req.url, `http://localhost:${PORT}`);

  if (req.method === 'POST' && url.pathname === '/api/v1/context/add') {
    let body;
    try {
      body = await readJson(req);
    } catch (e) {
      res.statusCode = 400;
      res.setHeader('content-type', 'application/json');
      res.end(JSON.stringify({ error: 'invalid json' }));
      return;
    }
    const docs = Array.isArray(body.documents) ? body.documents : [];
    const ctxId = 'mock_ctx_' + Math.random().toString(36).slice(2, 10);
    console.log(
      `[mock] /v1/context.add scope=${body.scope} ctx_type=${body.context_type} ` +
        `src=${body.source} docs=${docs.length} meta=${JSON.stringify(body.metadata)}`,
    );
    res.statusCode = 200;
    res.setHeader('content-type', 'application/json');
    res.end(
      JSON.stringify({
        success: true,
        context_id: ctxId,
        processed_documents: docs.length,
      }),
    );
    return;
  }

  if (req.method === 'POST' && url.pathname === '/api/v1/context/search') {
    let body;
    try {
      body = await readJson(req);
    } catch (e) {
      res.statusCode = 400;
      res.setHeader('content-type', 'application/json');
      res.end(JSON.stringify({ error: 'invalid json' }));
      return;
    }
    // Echo back canned context that matches the seeded articles, with the
    // query echoed as well so the LLM has something topical to work with.
    const query = String(body.query ?? '');
    console.log(`[mock] /v1/context.search scope=${body.scope} q=${JSON.stringify(query)}`);
    const canned = [
      `Topic echoed from search query: ${query}.`,
      'AI agents are REDACTEDnomous software systems built on top of large language models (LLMs). They plan multi-step workflows, call external tools, and reflect on their own outputs.',
      'Modern agentic systems combine planning, tool use, memory, and orchestration to REDACTEDmate knowledge work.',
      'Retrieval-Augmented Generation (RAG) augments LLM prompts with snippets retrieved from a vector store.',
    ];
    res.statusCode = 200;
    res.setHeader('content-type', 'application/json');
    res.end(
      JSON.stringify({
        contexts: canned.map((content, i) => ({
          content,
          score: 0.9 - i * 0.05,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        })),
      }),
    );
    return;
  }

  res.statusCode = 404;
  res.setHeader('content-type', 'application/json');
  res.end(JSON.stringify({ error: 'not_found', path: url.pathname }));
});

server.listen(PORT, '127.0.0.1', () => {
  console.log(`[mock] Alchemyst mock listening on http://127.0.0.1:${PORT}`);
});
